"use client";

import { useState } from "react";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
	Popover,
	PopoverContent,
	PopoverTrigger,
} from "@/components/ui/popover";
import { BellIcon } from "lucide-react";

const initialNotifications = [
	{
		id: 1,
		image: "/avatar-80-01.jpg",
		user: "Chris Tompson",
		action: "requested review on",
		target: "PR #42: Feature implementation",
		timestamp: "15 minutes ago",
		unread: true,
	},
	{
		id: 2,
		image: "/avatar-80-02.jpg",
		user: "Emma Davis",
		action: "shared",
		target: "New component library",
		timestamp: "45 minutes ago",
		unread: true,
	},
	{
		id: 3,
		image: "/avatar-80-03.jpg",
		user: "James Wilson",
		action: "assigned you to",
		target: "API integration task",
		timestamp: "4 hours ago",
		unread: false,
	},
	{
		id: 4,
		image: "/avatar-80-04.jpg",
		user: "Alex Morgan",
		action: "replied to your comment in",
		target: "Authentication flow",
		timestamp: "12 hours ago",
		unread: false,
	},
	{
		id: 5,
		image: "/avatar-80-05.jpg",
		user: "Sarah Chen",
		action: "commented on",
		target: "Dashboard redesign",
		timestamp: "2 days ago",
		unread: false,
	},
	{
		id: 6,
		image: "/avatar-80-06.jpg",
		user: "Miky Derya",
		action: "mentioned you in",
		target: "Origin UI open graph image",
		timestamp: "2 weeks ago",
		unread: false,
	},
];

function Dot({ className }: { className?: string }) {
	return (
		<svg
			width="6"
			height="6"
			fill="currentColor"
			viewBox="0 0 6 6"
			xmlns="http://www.w3.org/2000/svg"
			className={className}
			aria-hidden="true"
		>
			<circle cx="3" cy="3" r="3" />
		</svg>
	);
}

export default function Component() {
	const [notifications, setNotifications] = useState(initialNotifications);
	const unreadCount = notifications.filter((n) => n.unread).length;

	const handleMarkAllAsRead = () => {
		setNotifications(
			notifications.map((notification) => ({
				...notification,
				unread: false,
			}))
		);
	};

	const handleNotificationClick = (id: number) => {
		setNotifications(
			notifications.map((notification) =>
				notification.id === id
					? { ...notification, unread: false }
					: notification
			)
		);
	};

	return (
		<Popover>
			<PopoverTrigger asChild>
				<Button
					size="icon"
					variant="outline"
					className="relative"
					aria-label="Open notifications"
				>
					<BellIcon size={16} aria-hidden="true" />
					{unreadCount > 0 && (
						<Badge className="absolute -top-2 left-full min-w-5 -translate-x-1/2 px-1">
							{unreadCount > 99 ? "99+" : unreadCount}
						</Badge>
					)}
				</Button>
			</PopoverTrigger>
			<PopoverContent className="w-80 p-1">
				<div className="flex items-baseline justify-between gap-4 px-3 py-2">
					<div className="text-sm font-semibold">Notifications</div>
					{unreadCount > 0 && (
						<button
							className="text-xs font-medium hover:underline"
							onClick={handleMarkAllAsRead}
						>
							Mark all as read
						</button>
					)}
				</div>
				<div
					role="separator"
					aria-orientation="horizontal"
					className="bg-border -mx-1 my-1 h-px"
				></div>
				{notifications.map((notification) => (
					<div
						key={notification.id}
						className="hover:bg-accent rounded-md px-3 py-2 text-sm transition-colors"
					>
						<div className="relative flex items-start gap-3 pe-3">
							<img
								className="size-9 rounded-md"
								src={notification.image}
								width={32}
								height={32}
								alt={notification.user}
							/>
							<div className="flex-1 space-y-1">
								<button
									className="text-foreground/80 text-left after:absolute after:inset-0"
									onClick={() =>
										handleNotificationClick(notification.id)
									}
								>
									<span className="text-foreground font-medium hover:underline">
										{notification.user}
									</span>{" "}
									{notification.action}{" "}
									<span className="text-foreground font-medium hover:underline">
										{notification.target}
									</span>
									.
								</button>
								<div className="text-muted-foreground text-xs">
									{notification.timestamp}
								</div>
							</div>
							{notification.unread && (
								<div className="absolute inset-e-0 self-center">
									<Dot />
								</div>
							)}
						</div>
					</div>
				))}
			</PopoverContent>
		</Popover>
	);
}

import React from "react";

import { cn } from "@/lib/utils";
import { cva, type VariantProps } from "class-variance-authority";

const badgeVariants = cva(
	"inline-flex items-center rounded-full border px-2.5 py-0.5 text-xs font-semibold transition-colors focus:outline-hidden focus:ring-2 focus:ring-ring focus:ring-offset-2",
	{
		variants: {
			variant: {
				default:
					"border-transparent bg-primary text-primary-foreground hover:bg-primary/80",
				secondary:
					"border-transparent bg-secondary text-secondary-foreground hover:bg-secondary/80",
				destructive:
					"border-transparent bg-destructive text-destructive-foreground hover:bg-destructive/80",
				outline: "text-foreground",
			},
		},
		defaultVariants: {
			variant: "default",
		},
	}
);

export interface BadgeProps
	extends React.HTMLAttributes<HTMLDivElement>,
		VariantProps<typeof badgeVariants> {}

function Badge({ className, variant, ...props }: BadgeProps) {
	return (
		<div className={cn(badgeVariants({ variant }), className)} {...props} />
	);
}

export { Badge, badgeVariants };

import * as React from "react";

import { cn } from "@/lib/utils";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";

const buttonVariants = cva(
	"inline-flex items-center justify-center whitespace-nowrap rounded-md text-sm text-white hover:text-gray-400 font-medium ring-offset-background transition-colors focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50",
	{
		variants: {
			variant: {
				simple:
					"bg-secondary relative z-10 bg-transparent hover:border-secondary hover:bg-secondary/50  border border-transparent dark:text-white text-sm md:text-sm transition font-medium duration-200  rounded-md px-4 py-2  flex items-center justify-center",
				default: "bg-primary text-primary-foreground hover:bg-primary/90",
				destructive:
					"bg-destructive text-destructive-foreground hover:bg-destructive/90",
				outline:
					"border border-input bg-background hover:bg-accent hover:text-accent-foreground",
				secondary:
					"bg-secondary text-secondary-foreground hover:bg-secondary/80",
				ghost: "hover:bg-accent hover:text-black hover:stroke-black dark:text-white text-black",
				link: "text-primary underline-offset-4 hover:underline",
			},
			size: {
				default: "h-10 px-4 py-2",
				sm: "h-9 rounded-md px-3",
				lg: "h-11 rounded-md px-8",
				icon: "h-10 w-10",
			},
		},
		defaultVariants: {
			variant: "default",
			size: "default",
		},
	}
);

export interface ButtonProps
	extends React.ButtonHTMLAttributes<HTMLButtonElement>,
		VariantProps<typeof buttonVariants> {
	asChild?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
	({ className, variant, size, asChild = false, ...props }, ref) => {
		const Comp = asChild ? Slot : "button";
		return (
			<Comp
				className={cn(buttonVariants({ variant, size, className }))}
				ref={ref}
				{...props}
			/>
		);
	}
);
Button.displayName = "Button";

export { Button, buttonVariants };
